// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRoboto = makeLoadFont('Roboto');

// Module-level font loading
const { fontFamily: robotoFamily } = loadRoboto();



export type ComponentNameProps = Record<string, any>;

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#24334a",
  transparentBackground = false,
  durationInSeconds = 15,
  accentColorGreen = "#00ff73",
  accentColorCyan = "#00d5ff",
  heavyBlockText = "Heavy Image",
  optimizedFormatTexts = ["WebP", "AVIF", "Fast", "Opt"],
  scannerLogo = "G",
}) => {
  const frame = useCurrentFrame();
  const { width: W, height: H } = useVideoConfig();

  // Parser safety
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const safeTexts = optimizedFormatTexts.length > 0 ? optimizedFormatTexts : [""];

  // Conveyor & Animation Timings
  const spawnInterval = 45;
  const framesPhase1 = 100; // Left to center
  const framesPhase2 = 10;  // Inside machine
  const framesPhase3 = 70;  // Center to right

  const startX = -200;
  const enterX = W * 0.5;
  const exitX = W * 0.5;
  const endX = W - 150; // Falls into chest

  // Dynamically calculate active items based on current frame to ensure infinite looping support up to 60s
  const activeIds: number[] = [];
  const startId = Math.floor(frame / spawnInterval) - 5;
  for (let i = startId; i < startId + 15; i++) {
    activeIds.push(i);
  }

  // Scanner Beam Pulse
  const beamPulse = 0.5 + Math.sin(frame * 0.1) * 0.3;
  const scanLineOffset = (frame * 6) % (H * 0.4);
  const scanLineHalfWidth = 100 + (scanLineOffset / (H * 0.4)) * 150;

  // Car logic
  const carSpeed = 12;
  const carAge1 = frame * carSpeed;
  const car1X = (carAge1 % (W + 600)) - 300;
  
  const carAge2 = frame * carSpeed + 350;
  const car2RawX = (carAge2 % (W + 600)) - 300;
  const car2X = W - car2RawX;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: robotoFamily, overflow: "hidden" }}>
      
      {/* Background Gradient & Grid */}
      {!transparentBackground && (
        <div style={{ position: "absolute", inset: 0, background: "radial-gradient(circle at 50% 30%, rgba(255,255,255,0.15), rgba(0,0,0,0.7))", zIndex: 0 }} />
      )}
      <div style={{
        position: "absolute", top: 0, left: 0, right: 0, bottom: 0,
        backgroundImage: `linear-gradient(${accentColorCyan}22 2px, transparent 2px), linear-gradient(90deg, ${accentColorCyan}22 2px, transparent 2px)`,
        backgroundSize: "80px 80px",
        backgroundPosition: `center ${(frame * 1.5) % 80}px`,
        transform: "perspective(1000px) rotateX(50deg) scale(2.5)",
        transformOrigin: "top center",
        opacity: 0.4,
        zIndex: 1
      }} />

      {/* --- BOTTOM SECTION: DATA TRACKS & CARS (zIndex 5) --- */}
      <div style={{ position: "absolute", top: H * 0.8, left: 0, width: W, height: 100, zIndex: 5 }}>
        {/* Glowing Lines */}
        <div style={{ width: "100%", height: 4, backgroundColor: accentColorGreen, boxShadow: `0 0 15px ${accentColorGreen}`, marginTop: 20 }} />
        <div style={{ width: "100%", height: 4, backgroundColor: accentColorCyan, boxShadow: `0 0 15px ${accentColorCyan}`, marginTop: 40 }} />
        
        {/* Moving Pulses on tracks */}
        <div style={{ position: "absolute", left: ((frame * 18) % (W + 400)) - 200, top: 18, width: 80, height: 8, backgroundColor: "#fff", borderRadius: 4, boxShadow: `0 0 20px 5px ${accentColorGreen}`, filter: "blur(1px)" }} />
        <div style={{ position: "absolute", left: W - (((frame * 15 + 200) % (W + 400)) - 200), top: 58, width: 120, height: 8, backgroundColor: "#fff", borderRadius: 4, boxShadow: `0 0 20px 5px ${accentColorCyan}`, filter: "blur(1px)" }} />

        {/* Tech Cars */}
        {[
          { x: car1X, y: -20, color: accentColorGreen, flip: false },
          { x: car2X, y: 40, color: accentColorCyan, flip: true }
        ].map((car, i) => (
          <div key={i} style={{
            position: "absolute", left: car.x, top: car.y, width: 160, height: 60,
            backgroundColor: "#e6ebf2", borderRadius: "15px 30px 10px 15px",
            boxShadow: "10px 15px 25px rgba(0,0,0,0.5), inset -5px -5px 15px rgba(0,0,0,0.1)",
            display: "flex", flexDirection: "column", transform: car.flip ? "scaleX(-1)" : "none"
          }}>
            <div style={{ height: 30, display: "flex" }}>
              <div style={{ flex: 1, backgroundColor: "#4a72a8", margin: "6px 4px 0 15px", borderRadius: "8px 0 0 0", border: "2px solid #32527b" }} />
              <div style={{ flex: 0.8, backgroundColor: "#4a72a8", margin: "6px 15px 0 4px", borderRadius: "0 15px 0 0", border: "2px solid #32527b" }} />
            </div>
            <div style={{ height: 6, backgroundColor: car.color, margin: "5px 0", boxShadow: `0 0 10px ${car.color}` }} />
            <div style={{ position: "absolute", bottom: -12, left: 20, width: 24, height: 24, borderRadius: "50%", backgroundColor: "#1a1d24", border: "3px solid #8ea0b5" }}>
              <div style={{ width: "100%", height: "100%", border: "2px dashed #ccc", borderRadius: "50%", transform: `rotate(${frame * 12}deg)` }} />
            </div>
            <div style={{ position: "absolute", bottom: -12, right: 25, width: 24, height: 24, borderRadius: "50%", backgroundColor: "#1a1d24", border: "3px solid #8ea0b5" }}>
              <div style={{ width: "100%", height: "100%", border: "2px dashed #ccc", borderRadius: "50%", transform: `rotate(${frame * 12}deg)` }} />
            </div>
          </div>
        ))}
      </div>

      {/* --- GEARS & TIMER (zIndex 8) --- */}
      <div style={{ position: "absolute", left: 0, top: 0, width: W, height: H, zIndex: 8, pointerEvents: "none" }}>
        {/* Timer */}
        <div style={{ position: "absolute", left: 80, top: H * 0.28, width: 140, height: 140, backgroundColor: "#111", borderRadius: "50%", border: `6px solid #2a2f3a`, boxShadow: `0 0 40px rgba(0,0,0,0.8), 0 0 20px ${accentColorGreen}`, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
          {Array.from({ length: 12 }).map((_, i) => (
            <div key={i} style={{ position: "absolute", top: 8, left: 66, width: 4, height: i % 3 === 0 ? 14 : 6, backgroundColor: "#fff", transformOrigin: "4px 62px", transform: `rotate(${i * 30}deg)` }} />
          ))}
          <div style={{ position: "absolute", top: 25, left: 66, width: 5, height: 45, backgroundColor: accentColorGreen, transformOrigin: "bottom center", transform: `rotate(${frame * 5}deg)`, borderRadius: 3 }} />
          <div style={{ position: "absolute", top: 66, left: 66, width: 14, height: 14, backgroundColor: "#fff", borderRadius: "50%", transform: "translate(-5px, -5px)" }} />
          <div style={{ marginTop: 60, fontSize: 26, fontWeight: "900", color: accentColorGreen, textShadow: `0 0 10px ${accentColorGreen}` }}>{"<10"}</div>
        </div>
        {/* Gears */}
        {[
          { size: 200, x: 100, y: H * 0.45, speed: 1.5, color: "#5a5e66" },
          { size: 130, x: 230, y: H * 0.41, speed: -2.3, color: "#757c88" },
          { size: 160, x: 150, y: H * 0.56, speed: -1.8, color: "#4f5a6b" }
        ].map((g, i) => (
          <svg key={i} style={{ position: "absolute", left: g.x - g.size / 2, top: g.y - g.size / 2, width: g.size, height: g.size, transform: `rotate(${frame * g.speed}deg)` }} viewBox="0 0 100 100">
            <circle cx="50" cy="50" r="35" fill="none" stroke={g.color} strokeWidth="15" />
            <circle cx="50" cy="50" r="15" fill={g.color} />
            {Array.from({ length: 8 }).map((_, j) => (
              <rect key={j} x="42" y="0" width="16" height="15" fill={g.color} transform={`rotate(${j * 45} 50 50)`} rx="2" />
            ))}
          </svg>
        ))}
      </div>

      {/* --- MIDDLE SECTION: CONVEYOR BELT (zIndex 10) --- */}
      <div style={{ position: "absolute", left: 0, top: H * 0.5 + 40, width: W, height: 50, backgroundColor: "#1a1d24", borderTop: `6px solid ${accentColorCyan}`, borderBottom: "6px solid #0a0a0a", overflow: "hidden", zIndex: 10, boxShadow: "0 20px 30px rgba(0,0,0,0.5)" }}>
        {Array.from({ length: Math.ceil(W / 100) + 2 }).map((_, i) => {
          const rawX = (i * 100) + (frame * 6);
          const wrapX = (rawX % (W + 200)) - 100;
          return <div key={i} style={{ position: "absolute", left: wrapX, top: 0, width: 25, height: "100%", backgroundColor: "#2a2f3a", transform: "skewX(-30deg)" }} />
        })}
      </div>

      {/* --- CHEST LID (zIndex 14 - Behind Bubbles) --- */}
      <div style={{
        position: "absolute", left: W - 230, top: H * 0.5 - 110, width: 180, height: 110, zIndex: 14,
        backgroundColor: "#1a1d24", border: `4px solid ${accentColorCyan}`, borderRadius: "15px 15px 0 0",
        transform: "perspective(600px) rotateX(40deg)", transformOrigin: "bottom center",
        boxShadow: `inset 0 0 30px ${accentColorCyan}55`, display: "flex", flexWrap: "wrap", padding: 15, gap: 15
      }}>
        <div style={{ width: 35, height: 35, border: `2px solid ${accentColorGreen}`, borderRadius: "50%" }} />
        <div style={{ width: 35, height: 35, border: `2px solid ${accentColorGreen}`, borderRadius: "8px" }} />
        <div style={{ width: 35, height: 35, border: `2px solid ${accentColorCyan}`, borderRadius: "8px" }} />
      </div>

      {/* --- MACHINE BASE (zIndex 15 - Behind Blocks) --- */}
      <div style={{
        position: "absolute", left: W * 0.5 - 170, top: H * 0.5 - 150, width: 340, height: 280, zIndex: 15,
        backgroundColor: "#c5cbd4", borderRadius: 40, border: "6px solid #fff",
        boxShadow: "0 40px 60px rgba(0,0,0,0.6), inset 0 20px 40px rgba(255,255,255,0.8), inset 0 -20px 40px rgba(0,0,0,0.3)",
        display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center"
      }}>
        <div style={{ position: "absolute", top: -30, width: 100, height: 30, backgroundColor: "#1a1d24", borderRadius: "15px 15px 0 0", display: "flex", alignItems: "center", justifyContent: "center", border: `4px solid ${accentColorGreen}`, borderBottom: "none" }}>
          <div style={{ width: 50, height: 8, backgroundColor: accentColorGreen, borderRadius: 4, boxShadow: `0 0 15px ${accentColorGreen}` }} />
        </div>
        {/* Dark Hole for portal */}
        <div style={{ width: 180, height: 180, borderRadius: "50%", backgroundColor: "#0a101a" }} />
      </div>

      {/* --- ITEMS: BLOCKS & BUBBLES (zIndex 18) --- */}
      {activeIds.map(id => {
        const spawnFrame = id * spawnInterval;
        const age = frame - spawnFrame;
        const totalLife = framesPhase1 + framesPhase2 + framesPhase3;
        
        if (age < 0 || age > totalLife) return null;

        if (age <= framesPhase1) {
          // BLOCK PHASE
          const x = interpolate(age, [0, framesPhase1], [startX, enterX]);
          const scale = interpolate(age, [framesPhase1 - 15, framesPhase1], [1, 0], { extrapolateRight: "clamp" });
          return (
            <div key={`block-${id}`} style={{
              position: "absolute", left: x - 65, top: H * 0.5 - 90, transform: `scale(${scale})`, transformOrigin: "bottom center",
              width: 130, height: 130, backgroundColor: "#8ea0b5", borderRadius: 20, border: "4px solid #6b7a8f",
              boxShadow: "15px 15px 30px rgba(0,0,0,0.5), inset -10px -10px 20px rgba(0,0,0,0.2)",
              display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", zIndex: 18
            }}>
              <div style={{ position: "absolute", top: -24, width: 50, height: 24, border: "6px solid #4f5a6b", borderBottom: "none", borderRadius: "12px 12px 0 0" }} />
              <svg width="50" height="50" viewBox="0 0 24 24" fill="none" stroke="#4f5a6b" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <rect x="3" y="3" width="18" height="18" rx="2" ry="2" />
                <circle cx="8.5" cy="8.5" r="1.5" />
                <polyline points="21 15 16 10 5 21" />
              </svg>
              <div style={{ marginTop: 10, fontSize: 16, fontWeight: "900", color: "#4f5a6b", textTransform: "uppercase" }}>{heavyBlockText}</div>
            </div>
          );
        } else if (age > framesPhase1 + framesPhase2) {
          // BUBBLE PHASE
          const bubbleAge = age - framesPhase1 - framesPhase2;
          const x = interpolate(bubbleAge, [0, framesPhase3], [exitX, endX]);
          const progress = bubbleAge / framesPhase3;
          const arcY = Math.sin(progress * Math.PI) * -220; // Float arc
          
          // Scale up from portal, then scale down slightly as it falls in chest
          const scale = interpolate(bubbleAge, [0, 15, framesPhase3 - 10, framesPhase3], [0, 1, 1, 0.5], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
          const text = safeTexts[Math.abs(id) % safeTexts.length];

          return (
            <div key={`bub-${id}`} style={{
              position: "absolute", left: x - 45, top: H * 0.5 - 50 + arcY, transform: `scale(${scale})`, transformOrigin: "center",
              width: 90, height: 90, borderRadius: "50%",
              background: `radial-gradient(circle at 30% 30%, rgba(255,255,255,0.9), ${accentColorCyan} 60%, rgba(0,0,0,0.4))`,
              boxShadow: `0 0 30px ${accentColorCyan}, inset 0 0 20px #fff`,
              border: "2px solid rgba(255,255,255,0.7)", display: "flex", alignItems: "center", justifyContent: "center",
              color: "#fff", fontSize: 20, fontWeight: "bold", textShadow: "0 2px 5px rgba(0,0,0,0.5)", zIndex: 18
            }}>
              {text}
            </div>
          );
        }
        return null; // Inside machine
      })}

      {/* --- MACHINE PORTAL OVERLAY (zIndex 20 - Over Blocks) --- */}
      <div style={{
        position: "absolute", left: W * 0.5 - 90, top: H * 0.5 - 100, width: 180, height: 180, zIndex: 20,
        borderRadius: "50%", border: `10px solid #8ea0b5`, boxShadow: `inset 0 0 60px ${accentColorGreen}, 0 0 30px rgba(0,0,0,0.5)`,
        pointerEvents: "none", display: "flex", alignItems: "center", justifyContent: "center"
      }}>
        {Array.from({ length: 6 }).map((_, i) => (
          <div key={i} style={{
            position: "absolute", width: "90%", height: "90%", border: `4px solid ${accentColorGreen}`, borderRadius: "50%",
            borderLeftColor: "transparent", borderRightColor: "transparent",
            transform: `rotate(${frame * 3 + i * 60}deg) scale(${0.6 + (i * 0.08)})`, opacity: 0.6
          }} />
        ))}
        <div style={{ width: 50, height: 50, borderRadius: "50%", backgroundColor: "#fff", boxShadow: `0 0 40px 20px ${accentColorGreen}`, opacity: 0.8 }} />
      </div>

      {/* --- CHEST FRONT BODY (zIndex 25 - Over Bubbles) --- */}
      <div style={{
        position: "absolute", left: W - 240, top: H * 0.5 - 20, width: 200, height: 130, zIndex: 25,
        backgroundColor: "#2a2f3a", border: `4px solid ${accentColorCyan}`, borderRadius: "0 0 20px 20px",
        boxShadow: "0 30px 40px rgba(0,0,0,0.7), inset 0 20px 30px rgba(255,255,255,0.1)",
        display: "flex", alignItems: "center", justifyContent: "center"
      }}>
        <div style={{ position: "absolute", top: -10, left: 10, width: 172, height: 40, backgroundColor: accentColorCyan, filter: "blur(25px)", opacity: 0.8 }} />
        <div style={{ width: 80, height: 16, backgroundColor: "#1a1d24", borderRadius: 8, border: `2px solid ${accentColorCyan}` }} />
      </div>

      {/* --- TOP SECTION: SCANNER & BEAM (zIndex 30+) --- */}
      <svg style={{ position: "absolute", top: H * 0.12 + 140, left: 0, width: W, height: H * 0.4, zIndex: 30, opacity: beamPulse }}>
        <defs>
          <linearGradient id="beam" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={accentColorCyan} stopOpacity="0.8" />
            <stop offset="100%" stopColor={accentColorCyan} stopOpacity="0" />
          </linearGradient>
        </defs>
        <polygon points={`${W * 0.5 - 100},0 ${W * 0.5 + 100},0 ${W * 0.5 + 250},${H * 0.4} ${W * 0.5 - 250},${H * 0.4}`} fill="url(#beam)" />
        {/* Scanning Line */}
        <line x1={W * 0.5 - scanLineHalfWidth} y1={scanLineOffset} x2={W * 0.5 + scanLineHalfWidth} y2={scanLineOffset} stroke="#fff" strokeWidth="5" style={{ filter: `drop-shadow(0 0 10px ${accentColorCyan})` }} />
      </svg>

      <div style={{
        position: "absolute", top: H * 0.12, left: W * 0.5 - 140, width: 280, height: 280, zIndex: 35,
        borderRadius: "50%", background: "radial-gradient(circle at 40% 40%, rgba(255,255,255,0.4), rgba(255,255,255,0.05))",
        border: "4px solid rgba(255,255,255,0.7)", boxShadow: `0 30px 50px rgba(0,0,0,0.4), inset 0 0 50px ${accentColorCyan}`,
        backdropFilter: "blur(10px)", display: "flex", alignItems: "center", justifyContent: "center"
      }}>
        <div style={{ width: 220, height: 220, borderRadius: "50%", border: `6px dashed ${accentColorCyan}`, opacity: 0.6, transform: `rotate(${frame * 2}deg)` }} />
        <div style={{ position: "absolute", fontSize: 110, fontWeight: "900", color: "#fff", textShadow: `0 0 40px ${accentColorCyan}, 0 0 15px #fff` }}>
          {scannerLogo}
        </div>
      </div>

    </AbsoluteFill>
  );
};

export default ComponentName;